css:
@page {
    size: A4;
    margin: 1cm;
}

.final-amount {
    font-size: 24px;
    font-weight: bold;
}

.warning {
    padding: 10px;
    border: 1px solid #000;
    font-weight: bold;
    margin: 15px 0;
}

.service-table {
    width: 100%;
    border-collapse: collapse;
}

.service-table th,
.service-table td {
    border: 1px solid #000;
    padding: 6px;
}

@media print {

    .print-button,
    .btn,
    .interactive {
        display: none !important;
    }

    .page-break-after-10 {
        page-break-after: always;
    }
}
